module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in     ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [3:0] counter;
reg [9:0] sum;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        counter <= 4'b0000;
        sum <= 10'b0000000000;
        valid_out <= 1'b0;
    end
    else begin
        if (valid_in) begin
            counter <= counter + 1;
            sum <= sum + data_in;
        end

        if (counter == 4) begin
            valid_out <= 1'b1;
        end
        else begin
            valid_out <= 1'b0;
        end

        if (valid_out) begin
            data_out <= sum;
            counter <= 4'b0000;
            sum <= 10'b0000000000;
        end
    end
end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in    ,

    output  reg         valid_out    ,
    output  reg [9:0]   data_out
);

reg [9:0] accumulated_sum;
reg [2:0] counter;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        counter <= 3'b0;
        accumulated_sum <= 10'b0;
        valid_out <= 1'b0;
    end
    else begin
        if (valid_in) begin
            counter <= counter + 1;
            accumulated_sum <= accumulated_sum + data_in;
        end

        if (counter == 3'b100) begin
            valid_out <= 1'b1;
        end
        else begin
            valid_out <= 1'b0;
        end

        if (valid_out) begin
            data_out <= accumulated_sum;
            counter <= 3'b0;
            accumulated_sum <= 10'b0;
        end
    end
end

endmodule

