module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

    wire [7:0] c;
    assign {c[0], sum[0]} = a[0] + b[0] + cin;
    assign {c[1], sum[1]} = a[1] + b[1] + c[0];
    assign {c[2], sum[2]} = a[2] + b[2] + c[1];
    assign {c[3], sum[3]} = a[3] + b[3] + c[2];
    assign {c[4], sum[4]} = a[4] + b[4] + c[3];
    assign {c[5], sum[5]} = a[5] + b[5] + c[4];
    assign {c[6], sum[6]} = a[6] + b[6] + c[5];
    assign {cout, sum[7]} = a[7] + b[7] + c[6];

endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

    wire [7:0] c;
    assign c[0] = a[0] ^ b[0] ^ cin;
    assign sum[0] = a[0] ^ b[0] ^ cin;

    genvar i;
    generate
        for (i = 1; i < 8; i = i + 1) begin : gen_full_adder
            assign c[i] = (a[i] & b[i]) | (b[i] & c[i-1]) | (a[i] & c[i-1]);
            assign sum[i] = a[i] ^ b[i] ^ c[i-1];
        end
    endgenerate

    assign cout = c[7];

endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

    wire [7:0] c;
    wire [6:0] c_intermediate;

    assign {c[0], sum[0]} = a[0] + b[0] + cin;
    assign c_intermediate[0] = c[0];

    genvar i;
    generate
        for (i = 1; i < 8; i = i + 1) begin : full_adder_loop
            assign {c[i], sum[i]} = a[i] + b[i] + c_intermediate[i-1];
            assign c_intermediate[i] = c[i];
        end
    endgenerate

    assign cout = c[7];

endmodule

