module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

    wire [7:0] c;
    wire p, g;

    assign p = a ^ b;
    assign g = a & b;

    assign sum[0] = a[0] ^ b[0] ^ cin;
    assign c[0] = (a[0] & b[0]) | (a[0] & cin) | (b[0] & cin);

    genvar i;
    generate
        for (i = 1; i < 8; i = i + 1) begin : gen_loop
            assign sum[i] = p[i] ^ c[i - 1];
            assign c[i] = (p[i] & c[i - 1]) | (p[i] & g[i - 1]) | (c[i - 1] & g[i - 1]);
        end
    endgenerate

    assign cout = c[7];

endmodule

