);

    wire [7:0] sum_0;
    wire carry_0;
    wire [7:0] sum_1;

    eight_bit_adder adder_0 (
        .a(a[7:0]),
        .b(b[7:0]),
        .Cin(Cin),
        .y(sum_0),
        .Co(carry_0)
    );

    eight_bit_adder adder_1 (
        .a(a[15:8]),
        .b(b[15:8]),
        .Cin(carry_0),
        .y(sum_1),
        .Co(Co)
    );

    assign y = {sum_1, sum_0};

endmodule

