module eight_bit_adder (
    input wire [7:0] a,
    input wire [7:0] b,
    input wire Cin,
    output wire [7:0] y,
    output wire Co
);

    reg [7:0] sum;

    always @* begin
        sum[0] = a[0] ^ b[0] ^ Cin;
        sum[1] = a[1] ^ b[1] ^ ((a[0] & b[0]) | (a[0] & Cin) | (b[0] & Cin));
        sum[2] = a[2] ^ b[2] ^ ((a[1] & b[1]) | (a[1] & Cin) | (b[1] & Cin));
        sum[3] = a[3] ^ b[3] ^ ((a[2] & b[2]) | (a[2] & Cin) | (b[2] & Cin));
        sum[4] = a[4] ^ b[4] ^ ((a[3] & b[3]) | (a[3] & Cin) | (b[3] & Cin));
        sum[5] = a[5] ^ b[5] ^ ((a[4] & b[4]) | (a[4] & Cin) | (b[4] & Cin));
        sum[6] = a[6] ^ b[6] ^ ((a[5] & b[5]) | (a[5] & Cin) | (b[5] & Cin));
        sum[7] = a[7] ^ b[7] ^ ((a[6] & b[6]) | (a[6] & Cin) | (b[6] & Cin));
    end

    assign y = sum;
    assign Co = (a[7] & b[7]) | (a[7] & Cin) | (b[7] & Cin);

endmodule

