reg [DATA_WIDTH-1:0] b_reg;
reg [STG_WIDTH:0] carry_reg;
reg [DATA_WIDTH-1:0] sum_reg;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        a_reg <= 0;
        b_reg <= 0;
        carry_reg <= 0;
        sum_reg <= 0;
        o_en <= 0;
    end else if (i_en) begin
        a_reg <= adda;
        b_reg <= addb;
        carry_reg[0] <= 0;
        sum_reg <= a_reg + b_reg;
        for (int i = 0; i < DATA_WIDTH; i = i + STG_WIDTH) begin
            for (int j = 0; j < STG_WIDTH; j = j + 1) begin
                carry_reg[i+j+1] <= (sum_reg[i+j] + carry_reg[i+j]) >> 1;
                sum_reg[i+j] <= (sum_reg[i+j] + carry_reg[i+j]) & 1;
            end
        end
        o_en <= 1;
    end
end

assign result = {carry_reg[DATA_WIDTH], sum_reg};

endmodule

