	input					rrstn	,
	input 					winc	,
	input 			 		rinc	,
	input 		[WIDTH-1:0]	wdata	,

	output wire				wfull	,
	output wire				rempty	,
	output wire [WIDTH-1:0]	rdata
);

parameter ADDR_WIDTH = $clog2(DEPTH);

// Dual-port RAM
reg [WIDTH-1:0] ram [0:DEPTH-1];

// Write pointer
reg [ADDR_WIDTH-1:0] waddr_bin;
reg [ADDR_WIDTH-1:0] waddr_gray;
always @(posedge wclk or negedge wrstn) begin
	if (~wrstn) begin
		waddr_bin <= 0;
		waddr_gray <= 0;
	end
	else if (winc) begin
		waddr_bin <= waddr_bin + 1;
		waddr_gray <= waddr_bin ^ (waddr_bin >> 1);
	end
end

// Read pointer
reg [ADDR_WIDTH-1:0] raddr_bin;
reg [ADDR_WIDTH-1:0] raddr_gray;
always @(posedge rclk or negedge rrstn) begin
	if (~rrstn) begin
		raddr_bin <= 0;
		raddr_gray <= 0;
	end
	else if (rinc && ~rempty) begin
		raddr_bin <= raddr_bin + 1;
		raddr_gray <= raddr_bin ^ (raddr_bin >> 1);
	end
end

// Pointer synchronization
reg [ADDR_WIDTH-1:0] raddr_sync1;
reg [ADDR_WIDTH-1:0] raddr_sync2;
always @(posedge wclk) begin
	raddr_sync1 <= raddr_gray;
	raddr_sync2 <= raddr_sync1;
end

reg [ADDR_WIDTH-1:0] waddr_sync1;
reg [ADDR_WIDTH-1:0] waddr_sync2;
always @(posedge rclk) begin
	waddr_sync1 <= waddr_gray;
	waddr_sync2 <= waddr_sync1;
end

// Empty/full state detection
assign rempty = (waddr_gray == raddr_sync2);
assign wfull = ((waddr_gray ^ (waddr_sync1 >> 1)) == raddr_sync1);

// Read and write operations
assign rdata = ram[raddr_sync2];
always @(posedge wclk) begin
	if (winc) begin
		ram[waddr_sync2] <= wdata;
	end
end

endmodule

