        else
        begin
            cnt_10 <= cnt_10 + 1;
        end

        // Frequency divider for CLK_1 (1MHz)
        if (cnt_100 == 6'b110001)
        begin
            CLK_1 <= ~CLK_1;
            cnt_100 <= 6'b000000;
        end
        else
        begin
            cnt_100 <= cnt_100 + 1;
        end
    end
end

endmodule

