        if (start) begin
            if (i < 16) begin
                i <= i + 1;
                areg <= ain;
                breg <= bin;
                if (areg[i-1] == 1'b1) begin
                    yout_r <= yout_r + (breg << i);
                end
            end else if (i == 16) begin
                done_r <= 1;
