module multi_pipe_4bit#(
	parameter size = 4
)(
	input 						clk 		,   
	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

reg [N-1:0] partial_products [0:size-1];
reg [N-1:0] pipeline_reg1 [0:size-1];
reg [N-1:0] pipeline_reg2 [0:size-1];

integer i;

always @(posedge clk or negedge rst_n) begin
	if (~rst_n) begin
		for (i = 0; i < size; i = i + 1) begin
			pipeline_reg1[i] <= 0;
			pipeline_reg2[i] <= 0;
		end
	end else begin
		for (i = 0; i < size; i = i + 1) begin
			if (i == 0) begin
				partial_products[i] <= {2*N{1'b0}};
			end else begin
				partial_products[i] <= partial_products[i-1] << 1;
			end
			if (mul_b[i] == 1) begin
				partial_products[i] <= partial_products[i] + mul_a;
			end
			pipeline_reg1[i] <= partial_products[i];
		end
	end
end

always @(posedge clk) begin
	for (i = 0; i < size; i = i + 1) begin
		pipeline_reg2[i] <= pipeline_reg1[i];
		if (i == size-1) begin
			mul_out <= pipeline_reg2[i];
		end
	end
end

endmodule

module multi_pipe_4bit#(
	parameter size = 4
)(
	input 						clk 		,   
	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

reg [N-1:0] partial_products [0:size-1];
reg [N-1:0] pipeline_reg1, pipeline_reg2;

always @(posedge clk or negedge rst_n) begin
	if (~rst_n) begin
		pipeline_reg1 <= 0;
		pipeline_reg2 <= 0;
		for (int i = 0; i < size; i = i + 1) begin
			partial_products[i] <= 0;
		end
	end else begin
		pipeline_reg1 <= pipeline_reg2;
		pipeline_reg2 <= pipeline_reg1 + partial_products[size-1];
		for (int i = size-1; i > 0; i = i - 1) begin
			partial_products[i] <= partial_products[i-1];
		end
		partial_products[0] <= (mul_b[0]) ? (mul_a << 0) : 0;
		for (int i = 1; i < size; i = i + 1) begin
			partial_products[i] <= (mul_b[i]) ? (mul_a << i) : 0;
		end
	end
end

assign mul_out = pipeline_reg1;

endmodule

