			pipeline_reg2[i] <= pipeline_reg1[i];
		end
	end
end

always @ (posedge clk) begin
	mul_out <= pipeline_reg2[size-1];
end

endmodule

module multi_pipe_4bit#(
	parameter size = 4
)(
	input 						clk 		,   
	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

reg [N-1:0] partial_products [0:size-1];
reg [N-1:0] pipeline_reg1 [0:size-1];
reg [N-1:0] pipeline_reg2 [0:size-1];
reg [N-1:0] sum;

integer i, j;

always @(posedge clk or negedge rst_n) begin
	if (~rst_n) begin
		for (i = 0; i < size; i = i + 1) begin
			pipeline_reg1[i] <= 0;
			pipeline_reg2[i] <= 0;
			partial_products[i] <= 0;
		end
		sum <= 0;
	end else begin
		// Partial product generation
		for (i = 0; i < size; i = i + 1) begin
			if (mul_b[i] == 1'b1) begin
				partial_products[i] <= {mul_a, {i{1'b0}}};
			end else begin
				partial_products[i] <= 0;
			end
		end

		// Pipeline stages
		for (j = 0; j < size; j = j + 1) begin
			pipeline_reg1[j] <= partial_products[j] + pipeline_reg1[j];
			pipeline_reg2[j] <= pipeline_reg1[j];
		end

		// Final product calculation
		sum <= 0;
		for (i = 0; i < size; i = i + 1) begin
			sum <= sum + pipeline_reg2[i];
		end

		mul_out <= sum;
	end
end

endmodule

module multi_pipe_4bit#(
	parameter size = 4
)(
