	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

reg [N-1:0] pipeline_reg1 = 0;
reg [N-1:0] pipeline_reg2 = 0;

always @(posedge clk or negedge rst_n) begin
	if (~rst_n) begin
		pipeline_reg1 <= 0;
		pipeline_reg2 <= 0;
	end
	else begin
		// Partial product generation
		reg [N-1:0] partial_prod;
		always @* begin
			partial_prod = 0;
			for (int i = 0; i < size; i = i + 1) begin
				if (mul_b[i] == 1'b1) begin
					partial_prod = partial_prod + (mul_a << i);
				end
			end
		end

		// Pipeline registers
		pipeline_reg1 <= partial_prod;
		pipeline_reg2 <= pipeline_reg1;
		mul_out <= pipeline_reg2;
	end
end

endmodule

