   input [size-1:0] mul_a;       
   input [size-1:0] mul_b;       

   output reg mul_en_out;  
   output reg [size*2-1:0] mul_out;    

   reg [size-1:0] mul_a_reg;
   reg [size-1:0] mul_b_reg;
   reg [size*2-1:0] sum;
   reg mul_en_out_reg;
   reg [size*2-1:0] mul_out_reg;

   always @(posedge clk or negedge rst_n) begin
       if (~rst_n) begin
           mul_a_reg <= 0;
           mul_b_reg <= 0;
           sum <= 0;
           mul_en_out_reg <= 0;
           mul_out_reg <= 0;
       end else begin
           mul_a_reg <= mul_en_in ? mul_a : mul_a_reg;
           mul_b_reg <= mul_en_in ? mul_b : mul_b_reg;

           // Partial Product Calculation
           reg [size*2-1:0] partial_product;
           reg [size-1:0] shifted_mul_a;
           reg [size*2-1:0] shifted_mul_a_zero;
           reg [size*2-1:0] shifted_partial_product;
           reg [size*2-1:0] shifted_partial_product_zero;

           partial_product <= 0;
           shifted_mul_a_zero <= {size{1'b0}, mul_a_reg};
           shifted_partial_product_zero <= 0;

           // Pipeline Stages
           for (int i = 0; i < size; i = i + 1) begin
               shifted_mul_a <= {shifted_mul_a_zero[size-1], shifted_mul_a_zero[size-1:1]};
               shifted_partial_product <= shifted_mul_a & (mul_b_reg[i] ? 1'b1 : 1'b0);
               shifted_partial_product_zero <= {shifted_partial_product_zero[size-1], shifted_partial_product_zero[size-1:1]} + shifted_partial_product;
           end

           // Intermediate Sum Storage
           sum <= shifted_partial_product_zero + sum;

           // Final Product Register
           mul_out_reg <= sum;

           // Output Enable Signal
           mul_en_out_reg <= mul_en_in;
       end
   end

   assign mul_en_out = mul_en_out_reg;
   assign mul_out = (mul_en_out_reg[size*2-1] == 1'b1) ? mul_out_reg : 0;
end

