    output valid_out,
    output dout
);

    reg [3:0] data;
    reg [1:0] cnt;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            cnt <= 2'b00;
            valid_out <= 1'b0;
        end
        else begin
            if (cnt == 2'b11) begin
                cnt <= 2'b00;
                data <= d;
                valid_out <= 1'b1;
            end
            else begin
                cnt <= cnt + 1;
                valid_out <= 1'b1;
            end
        end
    end

    always @(*) begin
        case(cnt)
            2'b00: dout = data[3];
            2'b01: dout = data[2];
            2'b10: dout = data[1];
            2'b11: dout = data[0];
        endcase
    end

endmodule

