module pulse_detect(    
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state;
parameter IDLE = 2'b00, RISING_EDGE = 2'b01, FALLING_EDGE = 2'b10, PULSE_DETECTED = 2'b11;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= IDLE;
        data_out <= 0;
    end
    else begin
        case(state)
            IDLE: begin
                if (data_in & ~$past(data_in))
                    state <= RISING_EDGE;
            end
            RISING_EDGE: begin
                if (~data_in & $past(data_in))
                    state <= FALLING_EDGE;
            end
            FALLING_EDGE: begin
                if (~data_in & $past(data_in))
                    state <= PULSE_DETECTED;
            end
            PULSE_DETECTED: begin
                state <= IDLE;
            end
            default: state <= IDLE;
        endcase

        if (state == PULSE_DETECTED)
            data_out <= 1;
        else
            data_out <= 0;
    end
end

endmodule

module RAM (
	input clk,
	input rst_n,

	input write_en,
	input [7:0] write_addr,
	input [5:0] write_data,

	input read_en,
	input [7:0] read_addr,
	output reg [5:0] read_data
);

	reg [5:0] mem [7:0];

	// Reset logic
	always @(posedge clk or negedge rst_n)
	begin
		if (~rst_n)
		begin
			for (int i = 0; i < 8; i = i + 1)
				mem[i] <= 6'b000000;
		end
	end

	// Write operation
	always @(posedge clk)
	begin
		if (write_en)
			mem[write_addr] <= write_data;
	end

	// Read operation
	always @(posedge clk)
	begin
		if (read_en)
			read_data <= mem[read_addr];
		else
			read_data <= 6'b000000;
	end

endmodule

