    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [31:0] r;
    reg zero, carry, negative, overflow, flag;

    always @(*) begin
        case(aluc)
            ADD: r = a + b;
            ADDU: r = a + b;
            SUB: r = a - b;
            SUBU: r = a - b;
            AND: r = a & b;
            OR: r = a | b;
            XOR: r = a ^ b;
            NOR: r = ~(a | b);
            SLT: begin
                if (a < b) r = 32'b1;
                else r = 32'b0;
