module div_16bit(
    input wire [15:0] A,
    input wire [7:0] B,
    output wire [15:0] result,
    output wire [15:0] odd
    );

    reg [15:0] dividend;
    reg [15:0] quotient;
    reg [7:0] divisor;
    reg [7:0] remainder;

    always @(*) begin
        dividend = A;
        divisor = B;
        quotient = 16'b0;
        remainder = 8'b0;

        for (int i = 15; i >= 0; i = i - 1) begin
            remainder = {remainder, dividend[i]};
            if (remainder >= divisor) begin
                quotient[i] = 1;
                remainder = remainder - divisor;
            end
            else begin
                quotient[i] = 0;
            end
            remainder = remainder << 1;
        end
    end

    assign result = quotient;
    assign odd = remainder;

endmodule

