module traffic_light
    (
		input rst_n, 
        input clk, 
        input pass_request,
		output reg [7:0] clock,
        output reg red,
		output reg yellow,
		output reg green
    );

	parameter idle = 2'd0,
			  s1_red = 2'd1,
			  s2_yellow = 2'd2,
			  s3_green = 2'd3;

	reg [1:0] state, next_state;
	reg [7:0] cnt;
	reg p_red, p_yellow, p_green;

	always @(posedge clk or negedge rst_n) begin
		if (~rst_n) begin
			state <= idle;
			cnt <= 10;
		end
		else begin
			state <= next_state;
			cnt <= cnt - 1;
		end
	end

	always @* begin
		case(state)
			idle: begin
				if (pass_request && cnt > 10)
					next_state = s1_red;
				else
					next_state = s3_green;
			end
			s1_red: next_state = s2_yellow;
			s2_yellow: next_state = s1_red;
			s3_green: next_state = s2_yellow;
		endcase
	end

	always @(posedge clk or negedge rst_n) begin
		if (~rst_n) begin
			p_red <= 0;
			p_yellow <= 0;
			p_green <= 0;
		end
		else begin
			case(state)
				idle: begin
					p_red <= 1;
					p_yellow <= 0;
					p_green <= 0;
				end
				s1_red: begin
					p_red <= 0;
					p_yellow <= 0;
					p_green <= 1;
				end
				s2_yellow: begin
					p_red <= 0;
					p_yellow <= 1;
					p_green <= 0;
				end
				s3_green: begin
					p_red <= 1;
					p_yellow <= 0;
					p_green <= 0;
				end
			endcase
		end
	end

	always @(posedge clk) begin
		red <= p_red;
		yellow <= p_yellow;
		green <= p_green;
		clock <= cnt;
	end
endmodule

