        end
        else begin
            case(state)
                idle: begin
                    state <= s1_red;
                    cnt <= 8'h0A; // 10 cycles
                end
                s1_red: begin
                    if (cnt == 8'h0) begin
                        state <= s3_green;
                        cnt <= 8'h3C; // 60 cycles
                    end
                    else begin
                        state <= s2_yellow;
                        cnt <= 8'h0A; // 10 cycles
                    end
                end
