                        cnt <= 8'h0A; // 10 cycles
                    end
                    else if (cnt == 8'h0) begin
                        state <= s2_yellow;
                        cnt <= 8'h0A; // 10 cycles
                    end
                    else begin
                        state <= s3_green;
                        cnt <= cnt - 1;
                    end
                end
            endcase
        end
    end

    always @(posedge clk) begin
        case(state)
            idle: begin
                red <= 1'b1;
                yellow <= 1'b0;
                green <= 1'b0;
            end
            s1_red: begin
                red <= 1'b1;
                yellow <= 1'b0;
                green <= 1'b0;
